import './Footer.css';

/**
 * A simple footer displaying a copyright notice with an optional tagline.
 *
 * @param {object}   props
 * @param {string}   props.companyName  - Company name used in the copyright line.
 * @param {string}   [props.tagline]    - Optional tagline shown after the copyright.
 * @param {string}   [props.className]  - Extra class appended to root.
 * @param {object}   [props.style]      - Inline styles merged into root.
 */
export default function Footer({
  companyName,
  tagline,
  className = '',
  style,
}) {
  return (
    <footer className={`footer${className ? ' ' + className : ''}`} style={style}>
      <div className="footer-inner">
        <span className="footer-copy">&copy; 2026 {companyName}</span>
        {tagline && <span className="footer-tagline">{tagline}</span>}
      </div>
    </footer>
  );
}

import { useState } from 'react';
import FormField from './FormField.jsx';
import { validateRequiredFields } from '../utils/validate.js';
import './ContactForm.css';

/**
 * A self-contained contact form with name/email/message fields,
 * required-field validation, and a confirmation on success.
 *
 * @param {object}   props
 * @param {Array<{name:string,label:string,type?:string,multiline?:boolean}>} [props.fields]
 *        Field descriptors. Defaults to name, email, message.
 * @param {Record<string,string>} [props.labels]      - Custom labels keyed by field name.
 * @param {(data:Record<string,string>) => void} [props.onSubmit]
 *        Called with trimmed field values after successful validation.
 * @param {string}   [props.confirmationMessage]      - Message shown after submission.
 * @param {boolean}  [props.showConfirmation=true]     - Whether to show the confirmation banner.
 * @param {string}   [props.submitLabel='Send message'] - Text for the submit button.
 * @param {string}   [props.sendAnotherLabel='Send another'] - Text for the "send another" button.
 * @param {string}   [props.className]                - Extra class appended to root.
 * @param {object}   [props.style]                    - Inline styles merged into root.
 */
export default function ContactForm({
  fields: fieldsProp,
  labels,
  onSubmit,
  confirmationMessage = 'Thank you! Your message has been sent.',
  showConfirmation = true,
  submitLabel = 'Send message',
  sendAnotherLabel = 'Send another',
  className = '',
  style,
}) {
  const defaultFields = [
    { name: 'name', label: 'Name', type: 'text' },
    { name: 'email', label: 'Email', type: 'email' },
    { name: 'message', label: 'Message', multiline: true },
  ];

  const fields = fieldsProp || defaultFields;

  // Build initial state from field names
  const initialFormData = {};
  fields.forEach((f) => { initialFormData[f.name] = ''; });

  const [formData, setFormData] = useState(initialFormData);
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    // Clear error for this field on edit
    if (errors[name]) {
      setErrors((prev) => {
        const next = { ...prev };
        delete next[name];
        return next;
      });
    }
    // Reset submitted state on any edit
    if (submitted) setSubmitted(false);
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Build field-value map and labels
    const fieldValues = {};
    const errorLabels = {};
    fields.forEach((f) => {
      fieldValues[f.name] = formData[f.name] || '';
      errorLabels[f.name] = labels?.[f.name] || f.label || f.name.charAt(0).toUpperCase() + f.name.slice(1);
    });

    const validationErrors = validateRequiredFields(fieldValues, errorLabels);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) return;

    // Trim values
    const trimmed = {};
    fields.forEach((f) => { trimmed[f.name] = (formData[f.name] || '').trim(); });

    if (onSubmit) onSubmit(trimmed);

    // Reset form
    setFormData(initialFormData);
    setSubmitted(true);
  };

  const handleSendAnother = () => {
    setSubmitted(false);
  };

  const rootCls = ['contact-form', className].filter(Boolean).join(' ');

  return (
    <div className={rootCls} style={style}>
      {submitted && showConfirmation && (
        <div className="contact-form-confirmation">
          <span className="contact-form-confirmation-text">{confirmationMessage}</span>
          <button
            type="button"
            className="contact-form-send-another-btn"
            onClick={handleSendAnother}
          >
            {sendAnotherLabel}
          </button>
        </div>
      )}

      <form onSubmit={handleSubmit} noValidate>
        {fields.map((field) => (
          <FormField
            key={field.name}
            label={field.label}
            id={`contact-form-${field.name}`}
            name={field.name}
            type={field.type || 'text'}
            value={formData[field.name] || ''}
            onChange={handleChange}
            error={errors[field.name]}
            multiline={field.multiline || false}
          />
        ))}
        <button type="submit" className="contact-form-submit-btn">
          {submitLabel}
        </button>
      </form>
    </div>
  );
}

import './Header.css';

/**
 * A controlled header with a brand wordmark and mapped navigation buttons.
 *
 * @param {object}   props
 * @param {string}   props.brand        - Wordmark / logo text displayed on the left.
 * @param {string[]} props.pages        - Page names used as button labels and identifiers.
 * @param {string}   props.currentPage  - Currently active page name.
 * @param {(page: string) => void} props.onNavigate - Called with the page name on click.
 * @param {string}   [props.className]  - Extra class appended to root.
 * @param {object}   [props.style]      - Inline styles merged into root.
 */
export default function Header({
  brand,
  pages,
  currentPage,
  onNavigate,
  className = '',
  style,
}) {
  return (
    <header className={`header${className ? ' ' + className : ''}`} style={style}>
      <span className="header-brand">{brand}</span>
      <nav className="header-nav">
        {pages.map((page) => (
          <button
            key={page}
            className={`header-btn${currentPage === page ? ' header-btn-active' : ''}`}
            onClick={() => onNavigate(page)}
          >
            {page}
          </button>
        ))}
      </nav>
    </header>
  );
}

import './Section.css';

/**
 * A reusable section wrapper with a heading, optional description,
 * and an alternate styling variant.
 *
 * @param {object}   props
 * @param {string}   [props.id]          - DOM id for anchor linking.
 * @param {string}   props.heading       - Section heading text.
 * @param {string}   [props.description] - Optional paragraph below heading.
 * @param {boolean}  [props.alt]         - Alternate (darker) background variant.
 * @param {string}   [props.className]   - Extra class appended to root.
 * @param {object}   [props.style]       - Inline styles merged into root.
 * @param {ReactNode} props.children
 */
export default function Section({
  id,
  heading,
  description,
  alt,
  className = '',
  style,
  children,
}) {
  const cls = [
    'section',
    alt ? 'section-alt' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');
  return (
    <section id={id} className={cls} style={style}>
      <h2 className="section-heading">{heading}</h2>
      {description != null && (
        <p className="section-desc">{description}</p>
      )}
      {children}
    </section>
  );
}

import './PillNav.css';

/**
 * A row of pill-shaped buttons where exactly one item is active.
 * Each option can be a plain string (used as both value and label)
 * or an object `{ value, label }`.
 *
 * @param {object}   props
 * @param {Array<string|{value:string,label:string}>} props.options  - Pill labels/values.
 * @param {string}   props.active   - Currently selected value.
 * @param {(value: string) => void} props.onChange - Called with the clicked pill's value.
 * @param {string}   [props.className] - Extra class appended to root.
 * @param {object}   [props.style]     - Inline styles merged into root.
 */
export default function PillNav({
  options,
  active,
  onChange,
  className = '',
  style,
}) {
  return (
    <div className={`pill-nav${className ? ' ' + className : ''}`} style={style}>
      {options.map((option) => {
        const value = typeof option === 'string' ? option : option.value;
        const label = typeof option === 'string' ? option : option.label;
        return (
          <button
            key={value}
            className={`pill-nav-btn${active === value ? ' pill-nav-active' : ''}`}
            onClick={() => onChange(value)}
          >
            {label}
          </button>
        );
      })}
    </div>
  );
}

import './Timeline.css';

/**
 * A vertical timeline that renders a list of dated entries.
 * Each entry can have a date, title, subtitle (e.g., institution/company),
 * and an optional description.
 *
 * @param {object}   props
 * @param {Array<{
 *   date: string,
 *   title: string,
 *   subtitle?: string,
 *   description?: string,
 * }>} props.items  - Timeline entries to render.
 * @param {string}   [props.className]  - Extra class appended to root.
 * @param {object}   [props.style]      - Inline styles merged into root.
 */
export default function Timeline({
  items,
  className = '',
  style,
}) {
  const rootCls = ['timeline', className].filter(Boolean).join(' ');

  if (!items || items.length === 0) return null;

  return (
    <div className={rootCls} style={style}>
      {items.map((item, index) => (
        <div className="timeline-entry" key={index}>
          <div className="timeline-marker" />
          <div className="timeline-content">
            {item.date && <span className="timeline-date">{item.date}</span>}
            <h4 className="timeline-title">{item.title}</h4>
            {item.subtitle && <span className="timeline-subtitle">{item.subtitle}</span>}
            {item.description && <p className="timeline-desc">{item.description}</p>}
          </div>
        </div>
      ))}
    </div>
  );
}

import { useState, useEffect } from 'react';

/**
 * useState-like hook that persists state to localStorage.
 * On mount, reads the stored value (with JSON parse error handling).
 * On every update, writes the new value (with JSON stringify).
 *
 * @param {string} key          - localStorage key to read/write.
 * @param {unknown} initialValue - Fallback value if nothing is stored or parsing fails.
 * @returns {[unknown, (value: unknown) => void]} A stateful value and setter.
 *
 * @example
 * const [cart, setCart] = useLocalStorage('my-app-cart', []);
 * // cart is initialised from localStorage('my-app-cart') or []
 * // setCart(newCart) updates both state and localStorage
 */
export function useLocalStorage(key, initialValue) {
  const [storedValue, setStoredValue] = useState(() => {
    try {
      const raw = localStorage.getItem(key);
      return raw !== null ? JSON.parse(raw) : initialValue;
    } catch {
      return initialValue;
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(storedValue));
    } catch {
      // Storage full or unavailable — silently ignore so the app keeps working
    }
  }, [key, storedValue]);

  return [storedValue, setStoredValue];
}

import './NewsCard.css';

/**
 * A card for displaying a news article or similar item with title,
 * date, summary, and an optional action button.
 *
 * @param {object}   props
 * @param {string}   props.title          - Article / item title.
 * @param {string}   [props.date]         - Publication date string.
 * @param {string}   [props.summary]      - Short description or excerpt.
 * @param {() => void} [props.onClick]    - Called when the action button is clicked.
 * @param {string}   [props.actionLabel]  - Text for the action button (default "Read more").
 * @param {string}   [props.category]     - Optional category/tag label.
 * @param {string}   [props.className]    - Extra class appended to root.
 * @param {object}   [props.style]        - Inline styles merged into root.
 */
export default function NewsCard({
  title,
  date,
  summary,
  onClick,
  actionLabel = 'Read more',
  category,
  className = '',
  style,
}) {
  const rootCls = ['news-card', className].filter(Boolean).join(' ');

  return (
    <div className={rootCls} style={style}>
      {category && <span className="news-card-category">{category}</span>}
      <h3 className="news-card-title">{title}</h3>
      {date && <span className="news-card-date">{date}</span>}
      {summary && <p className="news-card-summary">{summary}</p>}
      {onClick && (
        <button className="news-card-action" onClick={onClick}>
          {actionLabel}
        </button>
      )}
    </div>
  );
}

import './SkillBar.css';

/**
 * A labelled progress bar that visually represents a skill percentage.
 *
 * @param {object}   props
 * @param {string}   props.label   - Skill name displayed above the bar.
 * @param {number}   props.percent - Percentage value (0–100). Clamped internally.
 * @param {string}   [props.className] - Extra class appended to root.
 * @param {object}   [props.style]     - Inline styles merged into root.
 */
export default function SkillBar({
  label,
  percent,
  className = '',
  style,
}) {
  const clamped = Math.min(100, Math.max(0, Number(percent) || 0));

  return (
    <div className={`skill-bar${className ? ' ' + className : ''}`} style={style}>
      <div className="skill-bar-header">
        <span className="skill-bar-label">{label}</span>
        <span className="skill-bar-pct">{clamped}%</span>
      </div>
      <div className="skill-bar-track">
        <div
          className="skill-bar-fill"
          style={{ width: `${clamped}%` }}
        />
      </div>
    </div>
  );
}

import './FormField.css';

/**
 * A labelled form field that renders either an <input> or a <textarea>
 * based on the `multiline` prop (or `type === 'textarea'`).
 *
 * @param {object}   props
 * @param {string}   props.label       - Label text displayed above the input.
 * @param {string}   props.id          - HTML id attribute for the input/textarea.
 * @param {string}   [props.name]      - Name attribute for the input/textarea.
 * @param {string}   [props.type]      - Input type (default 'text'). Use 'textarea' for a textarea.
 * @param {string}   props.value       - Controlled value.
 * @param {(e: React.ChangeEvent) => void} props.onChange - Change handler.
 * @param {string}   [props.error]     - Error message displayed below the field.
 * @param {boolean}  [props.multiline] - Alternative to type="textarea"; when true renders a textarea.
 * @param {string}   [props.className] - Extra class appended to root.
 * @param {object}   [props.style]     - Inline styles merged into root.
 */
export default function FormField({
  label,
  id,
  name,
  type = 'text',
  value,
  onChange,
  error,
  multiline = false,
  className = '',
  style,
}) {
  const isMultiline = multiline || type === 'textarea';
  const Tag = isMultiline ? 'textarea' : 'input';

  return (
    <div className={`form-field${className ? ' ' + className : ''}`} style={style}>
      <label htmlFor={id} className="form-field-label">{label}</label>
      <Tag
        id={id}
        name={name}
        type={isMultiline ? undefined : type}
        value={value}
        onChange={onChange}
        className="form-field-input"
      />
      {error && <div className="form-field-error">{error}</div>}
    </div>
  );
}

/**
 * Validates required fields and returns an object of error messages.
 * Fields whose trimmed value is empty get an error message.
 *
 * @param {Record<string, string>} fields - Object mapping field names to their values.
 * @param {Record<string, string>} [labels] - Optional custom labels for error messages.
 * @returns {Record<string, string>} Error messages keyed by field name.
 *
 * @example
 * const errors = validateRequiredFields({ name: '', email: 'a@b.com' });
 * // => { name: 'Name is required.' }
 *
 * @example
 * const errors = validateRequiredFields(
 *   { name: '', email: '' },
 *   { name: 'Full name', email: 'Email address' }
 * );
 * // => { name: 'Full name is required.', email: 'Email address is required.' }
 */
export function validateRequiredFields(fields, labels) {
  const errors = {};
  for (const [key, value] of Object.entries(fields)) {
    if (!value || !value.trim()) {
      const label = (labels && labels[key]) || key.charAt(0).toUpperCase() + key.slice(1);
      errors[key] = `${label} is required.`;
    }
  }
  return errors;
}

