  max-width: 640px;
}

.contact-form form {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.contact-form-confirmation {
  background-color: #2e7d32;
  color: #fff;
  padding: 1rem 1.5rem;
  border-radius: 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1.25rem;
