/* ===== Section ===== */

.section {
  padding: 2.5rem 1.5rem;
  max-width: 1100px;
  margin: 0 auto;
}

.section.section-alt {
  background-color: #e8e8e8;
  width: 100%;
  max-width: 100%;
}

.section-heading {
  text-align: center;
  font-size: 1.6rem;
  margin-bottom: 1rem;
}

.section-desc {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 2rem;
  font-size: 1rem;
  color: #444;
}

/* Responsive: tighten padding on small screens */
@media (max-width: 640px) {
  .section {
    padding: 1.75rem 1rem;
  }

  .section-heading {
    font-size: 1.3rem;
  }

  .section-desc {
    font-size: 0.95rem;
  }
}

/* ===== SkillBar ===== */

.skill-bar {
  margin-bottom: 1rem;
}

.skill-bar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.35rem;
}

.skill-bar-label {
  font-weight: 600;
  font-size: 0.9rem;
}

.skill-bar-pct {
  font-size: 0.85rem;
  font-weight: 500;
  opacity: 0.8;
}

.skill-bar-track {
  width: 100%;
  height: 10px;
  border-radius: 999px;
  background-color: #e0e0e0;
  overflow: hidden;
}

.skill-bar-fill {
  height: 100%;
  border-radius: 999px;
  background-color: currentColor;
  transition: width 0.5s ease;
}

@media (max-width: 640px) {
  .skill-bar-label {
    font-size: 0.85rem;
  }

  .skill-bar-track {
    height: 8px;
  }
}

/* ===== Timeline ===== */

.timeline {
  position: relative;
  padding-left: 2rem;
}

/* Vertical line */
.timeline::before {
  content: '';
  position: absolute;
  left: 0.5rem;
  top: 0;
  bottom: 0;
  width: 2px;
  background-color: currentColor;
  opacity: 0.2;
}

.timeline-entry {
  position: relative;
  padding-bottom: 1.75rem;
}

.timeline-entry:last-child {
  padding-bottom: 0;
}

.timeline-marker {
  position: absolute;
  left: -1.5rem;
  top: 0.25rem;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: currentColor;
  border: 2px solid #fff;
  box-shadow: 0 0 0 2px currentColor;
}

.timeline-content {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.timeline-date {
  font-size: 0.8rem;
  font-weight: 600;
  opacity: 0.7;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.timeline-title {
  font-size: 1rem;
  font-weight: 700;
  margin: 0;
  line-height: 1.3;
}

.timeline-subtitle {
  font-size: 0.9rem;
  font-weight: 500;
  opacity: 0.8;
}

.timeline-desc {
  font-size: 0.88rem;
  line-height: 1.5;
  margin: 0.25rem 0 0;
  opacity: 0.8;
}

@media (max-width: 640px) {
  .timeline {
    padding-left: 1.5rem;
  }

  .timeline-marker {
    left: -1rem;
    width: 10px;
    height: 10px;
  }

  .timeline-title {
    font-size: 0.95rem;
  }
}

/* ===== Global CSS Reset =====
 * Apply this at the root of your app:
 *   import '@shared-lib/src/utils/reset.css';
 *
 * Normalises box-sizing, spacing, typography, and full-height layout.
 * Does NOT set any brand colours — override them in your own App.css.
 */

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto,
    Oxygen, Ubuntu, Cantarell, sans-serif;
  line-height: 1.5;
  min-height: 100vh;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  font-size: inherit;
}

img {
  max-width: 100%;
  display: block;
}

ul, ol {
  list-style: none;
}
